using System;using System.IO;using Amagadon;
class EditorTest {static void Main(string[] args) {string d=Path.Combine(Path.GetDirectoryName(typeof(EditorTest).Assembly.Location),"editor-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);string source=Path.Combine(d,"ACE.exe");File.Copy(args[0],source);string output=EditorPatch.Prepare(d);if(Core.Hash(source)!=EditorPatch.InputHash || Core.Hash(output)!="0dcd1ad46936a9c5d90480b93e547bb1df2217d72dc0ea331b73f5645f7ac467")throw new Exception("hash mismatch");if(EditorPatch.Prepare(d)!=output)throw new Exception("reuse");if(args.Length>1){File.Copy(args[1],output,true);EditorPatch.Prepare(d);string[] backups=Directory.GetFiles(d,"ACE.Compat.exe.*.bak");if(backups.Length!=1 || Core.Hash(backups[0])!=Core.Hash(args[1]) || Core.Hash(output)!="0dcd1ad46936a9c5d90480b93e547bb1df2217d72dc0ea331b73f5645f7ac467")throw new Exception("legacy migration");}File.WriteAllText(output,"foreign");bool rejected=false;try{EditorPatch.Prepare(d);}catch(IOException){rejected=true;}if(!rejected || File.ReadAllText(output)!="foreign")throw new Exception("overwrite protection");rejected=false;try{EditorPatch.Build(new byte[10]);}catch(IOException){rejected=true;}if(!rejected)throw new Exception("input guard");if(Diagnostics.StartInfo(output,d).EnvironmentVariables.ContainsKey("__COMPAT_LAYER"))throw new Exception("editor input profile");Console.WriteLine("PASS: embedded editor recipe, exact output, original preservation, repeat preparation, foreign output and unsupported input rejection");}}
